import{_ as o,o as c,c as t,ae as r}from"./chunks/framework.BX6FPmO9.js";const p=JSON.parse('{"title":"LUI 搜尋入口","description":"","frontmatter":{},"headers":[],"relativePath":"product/lui-search.md","filePath":"product/lui-search.md"}'),d={name:"product/lui-search.md"};function s(a,e,i,n,l,u){return c(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="lui-搜尋入口" tabindex="-1">LUI 搜尋入口 <a class="header-anchor" href="#lui-搜尋入口" aria-label="Permalink to &quot;LUI 搜尋入口&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件描述首頁與 LUI（Language User Interface）搜尋的現況規格：流程、API、回應結構。</p><hr><h2 id="業務流程-現況" tabindex="-1">業務流程（現況） <a class="header-anchor" href="#業務流程-現況" aria-label="Permalink to &quot;業務流程（現況）&quot;">​</a></h2><ol><li>使用者開啟首頁，看到品牌、結果句與單一 composer（empty = marketing）；往下捲是訪客介紹。</li><li>使用者輸入問題（query），送出後切換為全幅對話工作區，呼叫 <strong>SSE</strong> <code>GET /api/chat?q=...</code>（可選 <code>sessionId</code>，見契約 <code>chatQueryParamsSchema</code>）。</li><li>伺服器回傳串流事件：先 <strong>meta</strong>（query、summary、confidence，可選 traceId），再 <strong>token</strong>（逐字/詞回答），最後 <strong>final</strong>（sources、nextSteps）與 <strong>done</strong>。應用層錯誤使用 <strong><code>failure</code></strong>（JSON <code>message</code>／<code>code</code>），<strong>不用</strong>事件名 <code>error</code>，以免與 <code>EventSource</code> 連線錯誤混淆。可選 <strong>tool_status</strong>（Phase 3+）。</li><li>前端以 <code>EventSource</code> 或等效方式消費 SSE；每則助手回答內嵌摘要／信心、串流正文、來源與下一步（無資料不畫空卡）。</li></ol><hr><h2 id="首頁與-ui" tabindex="-1">首頁與 UI <a class="header-anchor" href="#首頁與-ui" aria-label="Permalink to &quot;首頁與 UI&quot;">​</a></h2><ul><li><strong>路由</strong>：<code>app/routes/_index.tsx</code></li><li><strong>Loader</strong>：提供 SEO meta、i18n、structured data（JSON-LD）；版號與語系來自 root loader。</li><li><strong>空態</strong>：共用釘選 <code>WorkspaceTopbar</code>（Ask / Overview）→ <code>HomeLanding</code>（品牌 + 結果句 + 單一 <code>Composer</code>，填滿頂欄以下第一屏）→ <code>HomeIntro</code>（訪客介紹三 section）→ <code>WorkspaceFooter</code>。Typewriter 用短 hint；完整示範問題在 <code>data-testid=&quot;golden-question&quot;</code> chips。</li><li><strong>總覽</strong>：<code>/?view=dashboard</code> 為業務查詢地圖（個資與權限、資料從哪來、訂單相關），「問這題」連 <code>/?q=</code> 進入對話；可逛路徑連目錄／菜餚。頂欄與 Ask／對話共用，sticky 釘選。</li><li><strong>對話態</strong>：同一條頂欄加「新對話」；<code>WorkspaceChatView</code> 為 transcript（<code>role=&quot;log&quot;</code>）與置底 <code>Composer</code>。<code>ChatInterface</code> 消費 SSE；<code>AssistantTurn</code> 呈現結構化回覆。</li><li><strong><code>/?q=</code></strong>：總覽或外部連入時，Index 以該字串作為 <code>pendingQuery</code> 直接開對話。</li><li><strong>i18n</strong>：首頁文案由 <code>app/shared/i18n</code> 與 root 的 <code>translations</code> 提供；語系切換經 <code>POST /api/locale</code> + cookie。</li></ul><hr><h2 id="api-get-api-chat" tabindex="-1">API：GET /api/chat <a class="header-anchor" href="#api-get-api-chat" aria-label="Permalink to &quot;API：GET /api/chat&quot;">​</a></h2><ul><li><strong>查參</strong>：<code>q</code>（必填）；<code>sessionId</code>（選填，記憶／Phase 4 預留）</li><li><strong>回傳</strong>：SSE stream（穩定層；Zod：<code>@ai-search-portal/contracts</code>） <ul><li><code>meta</code>：<code>{ query, summary, confidence, traceId? }</code></li><li><code>token</code>：回答片段（字串）</li><li><code>final</code>：<code>{ sources: LuiSource[], nextSteps: string[] }</code></li><li><code>done</code>：結束</li><li><code>failure</code>（可選）：<code>{ message, code? }</code></li><li><code>tool_status</code>（可選）：<code>{ tool, status }</code></li></ul></li><li><strong>實作</strong>：<code>app/routes/api.chat.ts</code> 使用 <code>remix-utils/sse</code> 的 <code>eventStream</code> → <strong><code>app/services/chat-gateway.server.ts</code></strong>：預設同 process 呼叫 <strong><code>@ai-search-portal/agent-core</code></strong>；若設定 <strong><code>AGENT_RUNTIME_URL</code></strong> 則改以 HTTP 銜接 <strong><code>services/agent-runtime</code></strong>（內部 <code>internal.*</code> SSE 再映射為穩定事件）。Mock 回應仍來自 agent-core 的 <code>buildLuiResponse</code>（<code>app/services/lui.server.ts</code> re-export）。</li></ul><hr><h2 id="lui-回應結構-現況" tabindex="-1">LUI 回應結構（現況） <a class="header-anchor" href="#lui-回應結構-現況" aria-label="Permalink to &quot;LUI 回應結構（現況）&quot;">​</a></h2><ul><li><strong>LuiResponse</strong>：<code>summary</code>, <code>answer</code>, <code>confidence</code>, <code>sources</code>, <code>nextSteps</code></li><li><strong>LuiSource</strong>：<code>title</code>, <code>url</code></li><li>目前為 <strong>mock</strong>：固定範例文案與來源，無真實檢索或 LLM；<code>splitToTokens</code> 僅依空白分詞模擬串流。</li></ul><hr><h2 id="測試與-mock" tabindex="-1">測試與 Mock <a class="header-anchor" href="#測試與-mock" aria-label="Permalink to &quot;測試與 Mock&quot;">​</a></h2><ul><li>單元測試可 mock <code>buildLuiResponse</code> 或直接測 <code>lui.server.ts</code>。</li><li><code>AssistantTurn</code> 覆蓋 empty / streaming / complete / error 四態。</li><li>MSW 可攔截 <code>/api/chat</code> 回傳自訂 SSE 或 JSON（視測試需求）；現況 <code>app/test/handlers.ts</code> 為空陣列。</li></ul>',18)])])}const h=o(d,[["render",s]]);export{p as __pageData,h as default};
